class Ledger:
    def __init__(self):
        self.state = {"tags": ["stable"], "revision": 1}

    def add_tag(self, tag, persist):
        before = dict(self.state)
        self.state["tags"].append(tag)
        self.state["revision"] += 1
        if not persist(self.state):
            self.state = before
            return False
        return True

def has_quorum(votes):
    approvals = 0
    for vote in votes:
        if vote.get("approve"):
            approvals += 1
    return approvals >= 2

def dependency_order(graph, root):
    seen = set()
    result = []

    def visit(node):
        if node in seen:
            return
        seen.add(node)
        result.append(node)
        for dependency in graph.get(node, []):
            visit(dependency)

    visit(root)
    return result

class EventBus:
    def __init__(self):
        self.handlers = []

    def subscribe(self, handler):
        self.handlers.append(handler)

    def unsubscribe(self, handler):
        self.handlers.remove(handler)

    def emit(self, event):
        for handler in self.handlers:
            handler(event)
